import {tournamentScore} from './adult-tournament-state.js';
import {humanDuelProfile,DUEL_RULES_TEXT,TOURNAMENT_PURSE} from './tournament-duel-rules.js';
import {interactionChoice,activityQuote} from './interaction-ui-v40.js';
import {actionCostDetails} from './action-costs.js';
export function renderTournamentCard(s,ui,actions=[],{potionReason='Finish the waiting moment first.'}={}){
 const t=s.adultTournament;if(!t||t.stage==='offered')return '';
 const {e,button}=ui,q=tournamentScore(t),place=s.world.locations.find(p=>p.id===t.locationId)?.name||t.locationId,finished=t.stage==='finished';
 const label={preparing:'Preparation waiting',ready:'Between bouts',paused:'Suspended for ordinary life',bout:'A bout is in progress',finished:'A finished local card'}[t.stage];
 const results=t.results.map(r=>`<li>${e(t.opponents[r.boutIndex].name)}: ${r.outcome==='win'?'your win':r.outcome==='loss'?'your loss':'withdrawn'} · ${r.rounds} rounds · day ${r.day}. ${r.potionsStart-r.potionsEnd} carried ${r.potionsStart-r.potionsEnd===1?'potion':'potions'} used.</li>`).join('');
 const roster=t.opponents.map((p,i)=>{const profile=humanDuelProfile(p.profileId,t.difficulty);return `<p class="small-copy"><strong>${i+1}. ${e(p.name)}</strong> · ${e(p.role)} · ${e(profile.name)}. ${profile.hp} Health, ${profile.attackPower} power, ${profile.agility} agility, ${profile.armor} armor. ${e(profile.description)}</p>`;}).join('');
 const choices=actions.filter(a=>a.id.startsWith('tournament_')).map(a=>interactionChoice(ui,{label:a.label,op:'activity',id:a.id,description:a.description,meta:activityQuote(a,s),costDetails:actionCostDetails(s,a),disabledReason:a.disabledReason})).join('');
 const potion=!finished&&t.stage!=='bout'&&!s.event&&!s.conversations?.pending?interactionChoice(ui,{label:'Use a Carried Healing Potion',op:'use-consumable',id:'potions',description:'Use the ordinary Inventory action: spend one owned potion for up to 30 Health. No Focus, extra day or free supply.',meta:'1 owned potion · No time',disabledReason:potionReason}):'';
 const purse=t.prize?`${t.prize.amount} Gold awarded once on day ${t.prize.day}. No experience or equipment.`:finished?'No purse was awarded. This result cannot be replayed.':q.losses?`The recorded loss remains. The ${TOURNAMENT_PURSE} Gold three-win purse is no longer available; you may continue for the practice or stop.`:`Three actual wins earn one ${TOURNAMENT_PURSE} Gold purse. No experience, equipment, title or calling.`;
 return `<section class="panel tournament-card" data-tournament-card aria-label="The Watchhouse Challenge"><span class="eyebrow">${e(label)}</span><h2 tabindex="-1" data-tournament-heading>The Watchhouse Challenge</h2><p>${e(place)} · ${e(t.host.name)}, original administrator · ${e(t.jurisdiction.regionName)}.</p><p><strong>${q.wins} wins · ${q.losses} losses · ${q.played}/3 played bouts</strong></p><p class="small-copy">Preparation: ${t.paidDays}/1 actual day attended. ${t.paidDays?'That day is already paid in time.':'Only the remaining preparation day can be charged.'} Later care and travel retain their own costs.</p>${!finished?`<p>Health ${s.hero.hp}/${s.hero.maxHp} · Focus ${s.hero.mp}/${s.hero.maxMp} · Potions ${s.hero.potions}.</p>`:''}<p class="small-copy">${e(purse)}</p>${results?`<ol>${results}</ol>`:'<p class="small-copy">No bout result has been recorded.</p>'}<details data-disclosure="watchhouse-roster"><summary>Entrants and controlled-bout rules</summary>${roster}<p class="small-copy">${e(DUEL_RULES_TEXT)}</p></details>${!finished?`<div class="interaction-options">${choices}${potion}${t.stage==='paused'?button('Recovery and ordinary care','tournament-care','','ghost small'):''}</div>`:''}</section>`;
}
